import { spawn, execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, openSync, closeSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import { ownedProcesses, processes, signalOwned } from './spn135-local-processes.ts';
import type { ProcessRow } from './spn135-local-processes.ts';

async function main() {
  const directory = '/tmp/spn135-server-launch-probe';
  mkdirSync(directory, { recursive: true });
  const pkg = JSON.parse(readFileSync('package.json', 'utf8'));
  if (pkg.scripts.start !== 'node --max-old-space-size=256 --max-semi-space-size=8 server/index.ts' ||
    pkg.scripts.prestart || pkg.scripts.poststart) throw new Error('Unexpected start lifecycle');
  const results: unknown[] = [];
  for (const mode of ['npm', 'direct'] as const) {
    const database = `${directory}/${mode}-${Date.now()}.sqlite`;
    const configured = { PORT: '3108', HOST: '127.0.0.1', DATABASE_PATH: database,
      VITE_SYNC_EVIDENCE: '0', VITE_DOC_SELECTION_EVIDENCE: '0', VITE_DOC_RESPONSIVENESS_EVIDENCE: '1' };
    const log = openSync(`${directory}/${mode}.log`, 'w');
    const child = mode === 'npm' ? spawn('npm', ['start'], {
      env: { ...process.env, ...configured }, stdio: ['ignore', log, log], detached: true,
    }) : spawn(process.execPath, ['--max-old-space-size=256', '--max-semi-space-size=8', 'server/index.ts'], {
      env: { ...process.env, ...configured }, stdio: ['ignore', log, log], detached: true,
    });
    closeSync(log);
    if (!child.pid) throw new Error('Server did not start');
    let launchError: unknown;
    child.on('error', error => { launchError = error; });
    const known = new Map<number, ProcessRow>();
    const sample = () => ownedProcesses(processes(), child.pid!, known);
    const started = Date.now();
    let result: Record<string, unknown> = { mode, database, configured, node: process.version };
    try {
      let body: string | undefined;
      for (;;) {
        sample();
        if (launchError || child.exitCode !== null || child.signalCode !== null)
          throw new Error(`Server exited before ready: ${String(launchError)}`);
        try {
          const response = await fetch('http://127.0.0.1:3108/sign-in', { signal: AbortSignal.timeout(500) });
          if (response.status === 200) { body = await response.text(); break; }
        } catch {}
        if (Date.now() - started > 15_000) throw new Error('Sign-in readiness exceeded 15 seconds');
        await delay(100);
      }
      const readyMs = Date.now() - started;
      const snapshots: ProcessRow[][] = [];
      // Observe a bounded post-readiness interval; this is not a readiness sleep.
      for (let index = 0; index < 5; index++) { snapshots.push(sample()); if (index < 4) await delay(250); }
      const rows = snapshots.at(-1)!;
      const server = rows.find(row => row.command.includes('--max-old-space-size=256'));
      if (!server) throw new Error('Expected server child not observed');
      const executable = execFileSync('lsof', ['-a', '-p', String(server.pid), '-d', 'txt', '-Fn'], { encoding: 'utf8' }).split('\n').find(line => line.startsWith('n') && line.endsWith('/node'))?.slice(1);
      if (!executable) throw new Error('Loaded Node executable not observed');
      result = { ...result, outcome: 'ready', readyMs, responseSha256: createHash('sha256').update(body!).digest('hex'),
        serverExecutable: executable, snapshots, peakKiB: Math.max(...snapshots.map(rows => rows.reduce((sum, row) => sum + row.rssKiB, 0))) };
    } catch (error) {
      result = { ...result, outcome: 'failed', error: String(error) };
      throw error;
    } finally {
      sample(); signalOwned(known, 'SIGTERM', process.pid);
      const deadline = Date.now() + 2000;
      while (sample().length && Date.now() < deadline) await delay(50);
      if (sample().length) { signalOwned(known, 'SIGKILL', process.pid); await delay(100); }
      result.remaining = sample(); results.push(result);
      writeFileSync(`${directory}/results.json`, JSON.stringify(results, null, 2) + '\n');
      if ((result.remaining as ProcessRow[]).length) throw new Error('Server cleanup incomplete');
    }
    if (mode === 'direct') {
      const first = results[0] as Record<string, unknown>;
      if (result.responseSha256 !== first.responseSha256 || result.serverExecutable !== first.serverExecutable)
        throw new Error('Server response or executable differs');
    }
  }
  console.log(JSON.stringify(results.map((r: any) => ({mode:r.mode,outcome:r.outcome,readyMs:r.readyMs,peakKiB:r.peakKiB,serverExecutable:r.serverExecutable,remaining:r.remaining.length}))));
}
void main().catch(error => { console.error(error); process.exitCode = 1; });

